/**
 * @fileOverview    Sends authentication emails through Resend.
 * @module          features/auth
 *
 * @TODO            Replace magic strings with consts
 * @TODO            Pull DEFAULT_FROM from `.env`
 */

import {Resend} from "resend";

// TODO:: pull from .env (process.env.RESEND_FROM_EMAIL)
const DEFAULT_FROM = "Critter Forum <onboarding@resend.dev>";

/**
 * Sends an email-verification link.
 *
 * @param to       Recipient address.
 * @param url      Verification URL generated by Better Auth.
 */
export async function sendVerificationEmail(
    to: string,
    url: string,
): Promise<void> {

    const apiKey = process.env.RESEND_API_KEY;

    if (!apiKey) {
        throw new Error("RESEND_API_KEY is not configured.");
    }

    const resend = new Resend(apiKey);

    const {error} = await resend.emails.send({
        from: process.env.RESEND_FROM_EMAIL ?? DEFAULT_FROM,
        to,
        subject: "Confirm your new email address",
        text: [
            "You requested to change the email address for your Critter Forum account.",
            "",
            "Confirm your new email address by opening this link:",
            url,
            "",
            "If you did not request this change, you can ignore this email.",
        ].join("\n"),
    });

    if (error) {
        throw new Error(`Resend email delivery failed: ${error.message}`);
    }
}
